main.mjs:
// The sandbox's entry: one request is one judgment. The site (and the kit)
// sends { submission, seeds, capture } and gets back { verdict, logs } or
// { error, logs }. The secret seed never comes here, only this
// submission's two seeds (seeds.mjs).
import { begin, finish } from "./prelude.mjs";
import { createTools } from "./tools.mjs";
import { LIMITS, nestsDeeper } from "./verdict.mjs";

// The sender's code loads at the first judgment, so the prelude has always
// fixed the time, Math.random() and console before any of its lines run.
let loading;

function reply(body) {
  return new Response(JSON.stringify(body), {
    headers: { "content-type": "application/json" },
  });
}

function describe(error) {
  if (error instanceof Error)
    return `${error.name}: ${error.message}`.slice(0, 500);
  return String(error).slice(0, 500);
}

export default {
  async fetch(request) {
    const { submission, seeds, capture } = await request.json();
    let code;
    try {
      loading ??= import("./judge.js");
      code = await loading;
    } catch (error) {
      return reply({ error: { kind: "load", detail: describe(error) } });
    }
    if (typeof code.judge !== "function")
      return reply({
        error: { kind: "no-judge", detail: "judge.js 没有导出 judge 函数" },
      });
    const { tools, next } = createTools(submission, seeds);
    begin({ now: submission.now, next, capture });
    let verdict;
    try {
      verdict = await code.judge(structuredClone(submission), tools);
    } catch (error) {
      return reply({
        error: { kind: "threw", detail: describe(error) },
        logs: finish(),
      });
    }
    const logs = finish();
    // Too deep for JSON.stringify here on one machine and not another: the
    // same answer for all (verdict.mjs, state's depth).
    if (
      verdict !== null &&
      typeof verdict === "object" &&
      nestsDeeper(verdict, LIMITS.stateDepth + 1)
    )
      return reply({
        error: {
          kind: "invalid",
          detail: nestsDeeper(verdict.state, LIMITS.stateDepth)
            ? `state 嵌套超过 ${LIMITS.stateDepth} 层`
            : "返回的值转不成 JSON",
        },
        logs,
      });
    try {
      return reply({ verdict, logs });
    } catch {
      return reply({
        error: { kind: "invalid", detail: "返回的值转不成 JSON" },
        logs,
      });
    }
  },
};

prelude.mjs:
// The first module the sandbox evaluates, before the sender's code: it fixes
// what that code can lean on (协议第 4.3、4.4 节). Time and Math.random()
// only exist while judge() runs: at the top of the file they would differ
// from call to call.

const RealDate = Date;
let pinned = null;
let random = null;
let sink = null;

function notYet(what) {
  throw new Error(`${what} 只能在 judge 里用`);
}

class JudgeDate extends RealDate {
  constructor(...args) {
    if (args.length === 0 && pinned === null)
      throw new Error("new Date() 只能在 judge 里用");
    if (args.length > 0) super(...args);
    else super(pinned);
  }

  static now() {
    return pinned === null ? notYet("Date.now()") : pinned;
  }
}
globalThis.Date = JudgeDate;
Math.random = () => (random === null ? notYet("Math.random()") : random());

// Data could pass between 红包 through the cache: there is none here.
try {
  delete globalThis.caches;
} catch {}
if ("caches" in globalThis) {
  try {
    Object.defineProperty(globalThis, "caches", { value: undefined });
  } catch {}
}

function show(value) {
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    return String(value);
  }
}

// On the site console output is dropped; the kit asks for it.
for (const name of [
  "log",
  "info",
  "warn",
  "error",
  "debug",
  "trace",
  "dir",
  "table",
])
  console[name] = (...args) => {
    if (sink && sink.length < 200)
      sink.push(
        `${name === "log" ? "" : `${name}: `}${args.map(show).join(" ")}`.slice(
          0,
          2000,
        ),
      );
  };

/** Before judge(): the time, Math.random()'s stream and whether to keep console output. */
export function begin({ now, next, capture }) {
  pinned = now;
  random = next;
  sink = capture ? [] : null;
}

/** After judge(): the console output kept, if any. */
export function finish() {
  const logs = sink;
  pinned = null;
  random = null;
  sink = null;
  return logs ?? undefined;
}

